import * as THREE from 'three/webgpu';
import { 
  positionLocal, positionWorld, normalWorld, cameraPosition,
  texture, uv, uniform, float, vec3,
  mix, dot, normalize, sub, pow, add, mul
} from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const colors = {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
    ...(config.visual?.colors || {})
  };

  const accentColor = new THREE.Color(colors.accent);

  const imageUrl = config.assets?.imageUrl || '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = config.assets?.depthMapUrl || '/prism-mock/home/nodes/parallax-stack.depth.png';

  const mainTex = ctx.textureLoader(imageUrl);
  const depthTex = ctx.textureLoader(depthMapUrl);

  mainTex.colorSpace = THREE.SRGBColorSpace;
  mainTex.wrapS = THREE.ClampToEdgeWrapping;
  mainTex.wrapT = THREE.ClampToEdgeWrapping;
  depthTex.colorSpace = THREE.NoColorSpace;
  depthTex.wrapS = THREE.ClampToEdgeWrapping;
  depthTex.wrapT = THREE.ClampToEdgeWrapping;

  const srcRect = config.atlas?.sourceRect || [0, 0, 512, 320];
  const aspect = srcRect[2] / srcRect[3];
  const planeW = 4.0;
  const planeH = planeW / aspect;

  const geometry = new THREE.PlaneGeometry(planeW, planeH, 64, 64);

  const displacementScale = uniform(0.12);
  const rimIntensity = uniform(0.4);

  const depthVal = texture(depthTex, uv()).r;

  const material = new THREE.MeshPhysicalNodeMaterial({
    color: 0xffffff,
    metalness: 0.55,
    roughness: 0.5,
    clearcoat: 0.22,
    clearcoatRoughness: 0.6,
    side: THREE.DoubleSide
  });

  material.colorNode = texture(mainTex, uv());
  material.positionNode = vec3(
    positionLocal.x,
    positionLocal.y,
    positionLocal.z.add(depthVal.mul(displacementScale))
  );

  const viewDir = normalize(sub(cameraPosition, positionWorld));
  const fresnel = pow(float(1.0).sub(dot(normalWorld, viewDir)), 2.5);
  material.emissiveNode = mix(
    vec3(0.0, 0.0, 0.0),
    vec3(accentColor.r, accentColor.g, accentColor.b),
    fresnel.mul(rimIntensity)
  );

  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(-2.5, -1.1, 0);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(0.01, 0.01, 0.01);
  mesh.visible = false;
  mesh.renderOrder = 2;

  // Weighted-settle entrance (overshoot 1.04 -> 1.0, power4.out, 0.9s)
  const entranceTl = gsap.timeline({ delay: 0.4 });
  entranceTl
    .set(mesh, { visible: true })
    .to(mesh.scale, {
      x: 1.04, y: 1.04, z: 1.04,
      duration: 0.7,
      ease: 'power4.out'
    })
    .to(mesh.scale, {
      x: 1.0, y: 1.0, z: 1.0,
      duration: 0.2,
      ease: 'power4.out'
    });

  // Apply cinematic primitives
  const primitives = config.cinematicPrimitives || [];
  for (const prim of primitives) {
    if (ctx.primitives && ctx.primitives[prim.name]) {
      ctx.primitives[prim.name](mesh, prim.params || {});
    }
  }

  // Hover rise-in (subtle, 0.15 scene units)
  const baseY = -1.1;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(mesh.position, {
    y: baseY + 0.15,
    duration: 0.5,
    ease: 'power3.out'
  });

  // Event handlers
  mesh.userData.handlers = {
    pointerenter: () => {
      hoverTl.play();
    },
    pointerleave: () => {
      hoverTl.reverse();
    },
    click: () => {
      const pressTl = gsap.timeline();
      pressTl
        .to(mesh.scale, {
          x: 0.97, y: 0.97, z: 0.97,
          duration: 0.12,
          ease: 'back.out(1.7)'
        })
        .to(mesh.scale, {
          x: 1.0, y: 1.0, z: 1.0,
          duration: 0.2,
          ease: 'power3.out'
        });
      if (ctx.emit) {
        ctx.emit('hub-home.select', { source: 'quote-panel' });
      }
    }
  };

  // Cleanup
  mesh.userData.cleanup = () => {
    entranceTl.kill();
    hoverTl.kill();
    gsap.killTweensOf(mesh.scale);
    gsap.killTweensOf(mesh.position);
    geometry.dispose();
    material.dispose();
    mainTex.dispose();
    depthTex.dispose();
  };

  return mesh;
}
